  const navItems = [
    { id: 'dashboard', icon: 'fa-house', label: 'Home' },
    { id: 'programs', icon: 'fa-hand-holding-heart', label: 'Programs' },
    { id: 'reports', icon: 'fa-chart-pie', label: 'Impact' },
