import React, { useState } from 'react';
import { useApp } from '../App';
import { INITIAL_USERS } from '../services/mockData';
import { UserRole } from '../types';

const Login: React.FC = () => {
  const { setUser } = useApp();
  const [role, setRole] = useState<UserRole>(UserRole.DONATOR);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this would be an API call
    const user = INITIAL_USERS.find(u => u.role === role);
    if (user) {
      setUser(user);
    }
  };

  const roleConfigs = [
    { role: UserRole.DONATOR, label: 'Donator', icon: 'fa-heart', color: 'bg-rose-100 text-rose-600' },
    { role: UserRole.TRUSTEE, label: 'Trustee', icon: 'fa-shield-heart', color: 'bg-emerald-100 text-emerald-600' },
    { role: UserRole.BENEFICIARY, label: 'Beneficiary', icon: 'fa-people-roof', color: 'bg-blue-100 text-blue-600' },
    { role: UserRole.ADMIN, label: 'Admin', icon: 'fa-user-lock', color: 'bg-amber-100 text-amber-600' },
  ];

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <div className="w-full max-w-md bg-white p-8 rounded-3xl shadow-xl shadow-gray-200/50">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-emerald-600 rounded-2xl flex items-center justify-center text-white text-3xl font-bold mx-auto mb-4 shadow-lg shadow-emerald-200">W</div>
          <h1 className="text-2xl font-bold text-gray-900">Welcome Back</h1>
          <p className="text-gray-500 mt-2">Transparent welfare for everyone</p>
        </div>

        <div className="grid grid-cols-2 gap-3 mb-8">
          {roleConfigs.map((config) => (
            <button
              key={config.role}
              onClick={() => setRole(config.role)}
              className={`p-4 rounded-2xl border-2 transition-all flex flex-col items-center space-y-2 ${
                role === config.role 
                  ? 'border-emerald-500 bg-emerald-50' 
                  : 'border-gray-50 bg-gray-50 hover:border-gray-200'
              }`}
            >
              <div className={`w-10 h-10 rounded-full flex items-center justify-center ${config.color}`}>
                <i className={`fa-solid ${config.icon}`}></i>
              </div>
              <span className="text-xs font-semibold">{config.label}</span>
            </button>
          ))}
        </div>

        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
            <input 
              type="email" 
              placeholder="name@example.com"
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
            <input 
              type="password" 
              placeholder="••••••••"
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          <button 
            type="submit"
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-200 transition-all transform active:scale-95"
          >
            Sign In as {role.toLowerCase()}
          </button>
        </form>

        <p className="text-center text-gray-500 text-sm mt-8">
          Don't have an account? <span className="text-emerald-600 font-bold cursor-pointer hover:underline">Register Now</span>
        </p>
      </div>
    </div>
  );
};

