import React, { useState } from 'react';
import { useApp } from '../App';
import ProgramCard from '../components/ProgramCard';

const Programs: React.FC = () => {
  const { programs } = useApp();
  const [filter, setFilter] = useState('ALL');

  const categories = ['ALL', 'Health', 'Education', 'Relief', 'Infrastructure'];

  const filteredPrograms = filter === 'ALL' 
    ? programs 
    : programs.filter(p => p.category === filter);

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Welfare Programs</h1>
          <p className="text-gray-500">Explore and support causes</p>
        </div>
        <button className="w-10 h-10 bg-white border border-gray-100 rounded-xl flex items-center justify-center text-gray-400">
          <i className="fa-solid fa-sliders"></i>
        </button>
      </header>

      <div className="flex space-x-2 overflow-x-auto pb-2 scrollbar-hide">
        {categories.map(cat => (
          <button
            key={cat}
            onClick={() => setFilter(cat)}
            className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap transition-all ${
              filter === cat 
                ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                : 'bg-white text-gray-500 border border-gray-100'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      <div className="grid sm:grid-cols-2 gap-6">
        {filteredPrograms.map(p => (
          <ProgramCard key={p.id} program={p} />
        ))}
      </div>

      {filteredPrograms.length === 0 && (
        <div className="text-center py-20">
          <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
            <i className="fa-solid fa-magnifying-glass text-3xl"></i>
          </div>
          <p className="text-gray-500 font-medium">No programs found in this category.</p>
        </div>
      )}
    </div>
  );
};

