                </div>
                <span className={`px-2 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider ${
                  app.status === 'PENDING' ? 'bg-amber-50 text-amber-600' : 'bg-emerald-50 text-emerald-600'
                }`}>
                  {app.status}
                </span>
              </div>

              <div className="bg-gray-50 p-4 rounded-xl mb-4">
                <p className="text-xs font-bold text-gray-500 mb-2">ATTACHED DOCUMENTS</p>
                <div className="flex flex-wrap gap-2">
                  {app.documents.map(doc => (
                    <div key={doc} className="flex items-center bg-white px-3 py-1.5 rounded-lg border border-gray-100 text-xs font-medium text-emerald-600 cursor-pointer">
                      <i className="fa-solid fa-file-pdf mr-2"></i> {doc}
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex space-x-3">
                <button className="flex-grow bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-2 rounded-xl text-sm transition-colors">
                  Approve Application
                </button>
                <button className="px-4 py-2 bg-rose-50 text-rose-600 font-bold rounded-xl text-sm border border-rose-100">
                  Reject
