    setUsers(prev => [newUser, ...prev]);
  };

  const addExpense = (data: Omit<Expense, 'id' | 'date' | 'trusteeId'>) => {
    if (!user) return;
    const newExpense: Expense = {
      ...data,
      id: `e-${Date.now()}`,
      date: new Date().toISOString(),
      trusteeId: user.id
    };
    setExpenses(prev => [newExpense, ...prev]);
  };

  const renderView = () => {
    if (!user) {
      if (view === 'login') return <Login />;
      return <Home />;
    }

    switch (view) {
      case 'dashboard': return <Dashboard />;
      case 'programs': return <Programs />;
      case 'reports': return <Reports />;
      case 'profile': return <Profile />;
      case 'trustees': return <TrusteeManagement />;
      case 'beneficiaries': return <BeneficiaryManagement />;
      default: return <Dashboard />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      user, setUser: handleSetUser, programs, setPrograms, 
      donations, setDonations, expenses, setExpenses, 
      users, setUsers, applications, setApplications,
      view, setView, logout,
      addDonation, addApplication, updateApplicationStatus, addProgram, addUser, addExpense
    }}>
      <div className="min-h-screen flex flex-col pb-20 md:pb-0 bg-[#f8fafc]">
        {user && <Navbar />}
        <main className={`flex-grow ${view === 'home' ? '' : 'container mx-auto px-4 py-6 md:py-10 max-w-full lg:max-w-6xl xl:max-w-7xl'} transition-all duration-300`}>
          {renderView()}
        </main>
        {user && <BottomNav />}
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState } from 'react';
import { useApp } from '../App';
import { INITIAL_USERS } from '../services/mockData';
import { UserRole } from '../types';

const Login: React.FC = () => {
  const { setUser, addUser, setView } = useApp();
  const [isRegistering, setIsRegistering] = useState(false);
  const [role, setRole] = useState<UserRole>(UserRole.DONATOR);
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    if (isRegistering) {
      if (!name || !email || !password) {
        alert('Please fill in all fields');
        return;
      }
      addUser({
        name,
        email,
        role,
        avatar: `https://ui-avatars.com/api/?name=${name}&background=random`
      });
      alert('Registration successful! You can now log in.');
      setIsRegistering(false);
    } else {
      const user = INITIAL_USERS.find(u => u.role === role);
      if (user) {
        setUser(user);
      } else {
        alert('Invalid credentials for this role.');
      }
    }
  };

  const quickLogin = (targetRole: UserRole) => {
    const user = INITIAL_USERS.find(u => u.role === targetRole);
    if (user) {
      setUser(user);
