import { useApp, FIRST_ADMIN_ID } from '../App';
import { UserRole } from '../types';

const TrusteeManagement: React.FC = () => {
  const { users, addUser, user } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '' });

  const trustees = users.filter(u => u.role === UserRole.TRUSTEE);
  const isFirstAdmin = user?.id === FIRST_ADMIN_ID;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isFirstAdmin) {
      alert("Only the 1st Admin can add trustees.");
      return;
    }
    addUser({
      name: formData.name,
      email: formData.email,
      role: UserRole.TRUSTEE,
      avatar: `https://picsum.photos/seed/${formData.name}/200`
    });
    setFormData({ name: '', email: '' });
    setIsModalOpen(false);
    alert('New Trustee added successfully!');
  };

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Manage Trustees</h1>
          <p className="text-gray-500">{trustees.length} active field officers</p>
        </div>
        {isFirstAdmin && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-emerald-600 text-white w-12 h-12 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-200 hover:bg-emerald-700 transition-colors"
          >
            <i className="fa-solid fa-plus text-lg"></i>
          </button>
        )}
      </header>

      <div className="grid md:grid-cols-2 gap-4">
        {trustees.map(trustee => (
          <div key={trustee.id} className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm flex items-center justify-between hover:border-emerald-100 transition-colors">
            <div className="flex items-center space-x-4">
              <img src={trustee.avatar || `https://ui-avatars.com/api/?name=${trustee.name}`} className="w-14 h-14 rounded-xl border border-gray-50" alt={trustee.name} />
              <div>
                <h3 className="font-bold text-gray-900">{trustee.name}</h3>
                <p className="text-xs text-gray-400">{trustee.email}</p>
                <div className="flex space-x-2 mt-1">
                  <span className="px-1.5 py-0.5 bg-emerald-50 text-emerald-600 text-[10px] font-bold rounded uppercase tracking-wider">Active</span>
                </div>
              </div>
            </div>
            {isFirstAdmin && (
              <div className="flex space-x-1">
                <button className="p-2.5 text-gray-300 hover:text-blue-500 transition-colors"><i className="fa-solid fa-pen"></i></button>
                <button className="p-2.5 text-gray-300 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash"></i></button>
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="bg-emerald-50 p-6 rounded-3xl border border-emerald-100 mt-8">
        <h3 className="text-emerald-900 font-bold mb-2 flex items-center">
          <i className="fa-solid fa-shield-halved mr-2"></i> Trustee Protocols
        </h3>
        <ul className="text-emerald-700 text-xs space-y-2 list-disc pl-5">
          <li>Verify beneficiary eligibility on-ground before disbursement.</li>
          <li>Upload digital copies of all receipts immediately after purchase.</li>
          <li>Conduct bi-weekly site visits to ongoing projects.</li>
        </ul>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-sm rounded-3xl p-8 shadow-2xl">
            <h3 className="text-xl font-bold mb-6">Register New Trustee</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Full Name</label>
                <input 
                  required
                  className="w-full p-4 bg-gray-50 border border-gray-100 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  placeholder="e.g. Hassan Ali"
                />
              </div>
              <div>
                <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Official Email</label>
                <input 
                  required
                  type="email"
                  className="w-full p-4 bg-gray-50 border border-gray-100 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500"
                  value={formData.email}
                  onChange={e => setFormData({...formData, email: e.target.value})}
                  placeholder="hassan@albadar.org"
                />
              </div>
              <div className="flex space-x-3 pt-4">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-grow py-4 rounded-xl font-bold text-gray-400 bg-gray-50">Cancel</button>
                <button type="submit" className="flex-grow py-4 rounded-xl font-bold text-white bg-emerald-600 shadow-lg shadow-emerald-100">Add User</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TrusteeManagement;

