import React, { useState } from 'react';
import { useApp } from '../App';
import { UserRole } from '../types';

const Login: React.FC = () => {
  const { setUser, addUser, setView, users } = useApp();
  const [isRegistering, setIsRegistering] = useState(false);
  const [role, setRole] = useState<UserRole>(UserRole.DONATOR);
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    if (isRegistering) {
      if (!name || !email || !password) {
        alert('Please fill in all fields');
        return;
      }
      addUser({
        name,
        email,
        role,
        password,
        avatar: `https://ui-avatars.com/api/?name=${name}&background=random`
      });
      alert('Registration successful! You can now log in.');
      setIsRegistering(false);
    } else {
      // Find user in the live state
      const foundUser = users.find(u => u.email === email && u.role === role);

      // If user has a password set, check it. Otherwise, simple role-based login for existing mocks.
      if (foundUser) {
        if (foundUser.password && foundUser.password !== password) {
          alert('Incorrect password.');
          return;
        }
        setUser(foundUser);
      } else {
        alert('User not found or invalid credentials for this role.');
      }
    }
  };

  const quickLogin = (targetRole: UserRole) => {
    const foundUser = users.find(u => u.role === targetRole);
    if (foundUser) {
      setUser(foundUser);
    }
  };

  const roleConfigs = [
    { role: UserRole.DONATOR, label: 'Donator', icon: 'fa-heart', color: 'bg-rose-100 text-rose-600' },
    { role: UserRole.TRUSTEE, label: 'Trustee', icon: 'fa-shield-heart', color: 'bg-emerald-100 text-emerald-600' },
    { role: UserRole.BENEFICIARY, label: 'Beneficiary', icon: 'fa-people-roof', color: 'bg-blue-100 text-blue-600' },
    { role: UserRole.ADMIN, label: 'Admin', icon: 'fa-user-lock', color: 'bg-amber-100 text-amber-600' },
  ];

  return (
    <div className="flex flex-col items-center justify-center min-h-[90vh] px-4 py-8 relative">
      {/* Back to Home Button */}
      <button 
        onClick={() => setView('home')}
        className="mb-8 flex items-center space-x-2 text-gray-400 hover:text-emerald-600 font-bold transition-all group"
      >
        <div className="w-8 h-8 rounded-full bg-white shadow-sm flex items-center justify-center group-hover:bg-emerald-50 transition-all">
          <i className="fa-solid fa-arrow-left text-xs"></i>
        </div>
        <span>Back to Home</span>
      </button>

      <div className="w-full max-w-[420px] bg-white p-10 rounded-[40px] shadow-2xl shadow-gray-200/50 border border-gray-50">
        <div className="text-center mb-10">
          <div className="w-20 h-20 bg-emerald-600 rounded-[28px] flex items-center justify-center text-white text-4xl font-bold mx-auto mb-6 shadow-xl shadow-emerald-200 ring-4 ring-white transition-transform hover:scale-105">A</div>
          <h1 className="text-3xl font-extrabold text-[#111827] leading-tight">Albadar Welfare Trust</h1>
          <p className="text-gray-400 font-medium mt-3 text-lg">
            {isRegistering ? 'Create your account' : 'Transparent welfare for everyone'}
          </p>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-10">
          {roleConfigs.map((config) => (
            <button
              key={config.role}
              onClick={() => setRole(config.role)}
              className={`p-5 rounded-3xl border-2 transition-all duration-300 flex flex-col items-center space-y-3 ${
                role === config.role 
                  ? 'border-emerald-500 bg-emerald-50 shadow-md' 
                  : 'border-gray-50 bg-[#F9FAFB] hover:border-gray-200'
              }`}
            >
              <div className={`w-12 h-12 rounded-full flex items-center justify-center shadow-sm ${config.color}`}>
                <i className={`fa-solid ${config.icon} text-lg`}></i>
              </div>
              <span className={`text-sm font-bold ${role === config.role ? 'text-emerald-800' : 'text-gray-600'}`}>
                {config.label}
              </span>
            </button>
          ))}
        </div>

        <form onSubmit={handleAuth} className="space-y-6">
          {isRegistering && (
            <div className="space-y-2">
              <label className="block text-sm font-bold text-gray-700 ml-1">Full Name</label>
              <input 
                type="text" 
                placeholder="John Doe"
                className="w-full px-5 py-4 rounded-2xl bg-gray-50 border border-gray-100 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-medium"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
          )}
          <div className="space-y-2">
            <label className="block text-sm font-bold text-gray-700 ml-1">Email Address</label>
            <input 
              type="email" 
              placeholder="name@example.com"
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 border border-gray-100 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-medium"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <label className="block text-sm font-bold text-gray-700 ml-1">Password</label>
            <input 
              type="password" 
              placeholder="••••••••"
              className="w-full px-5 py-4 rounded-2xl bg-gray-50 border border-gray-100 focus:bg-white focus:ring-2 focus:ring-emerald-500 outline-none transition-all font-medium"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>
          <button 
            type="submit"
            className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold py-5 rounded-2xl shadow-xl shadow-emerald-100 transition-all transform active:scale-95 text-lg"
          >
            {isRegistering ? 'Create Account' : 'Sign In'}
          </button>
        </form>

        <p className="text-center text-gray-500 text-sm mt-8">
          {isRegistering ? 'Already have an account?' : "Don't have an account?"} {' '}
          <button 
            onClick={() => setIsRegistering(!isRegistering)}
            className="text-emerald-600 font-bold hover:underline"
          >
            {isRegistering ? 'Sign In Now' : 'Register Now'}
          </button>
        </p>

        {!isRegistering && (
          <div className="mt-12 pt-8 border-t border-gray-50">
            <p className="text-center text-[10px] font-black text-gray-300 uppercase tracking-[0.2em] mb-5">Dev Quick Access</p>
            <div className="grid grid-cols-2 gap-2">
              {roleConfigs.map(c => (
                <button 
                  key={c.role}
                  onClick={() => quickLogin(c.role)}
                  className="py-2.5 px-3 rounded-xl bg-gray-50 text-gray-400 text-[11px] font-bold border border-gray-100 hover:bg-white hover:text-emerald-600 hover:border-emerald-200 transition-all"
                >
                  {c.label}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

